sn_aia_tool.script:
/**
 * Search_Knowledge_Base
 * Queries ServiceNow Knowledge Base articles relevant to a banking customer inquiry.
 *
 * @param {Object} inputs
 * @param {string} inputs.query - The customer's question or search term
 * @returns {Object} kb_results
 */
(function executeScript(inputs, outputs) {
  var query = inputs.query || '';

  if (!query) {
    outputs.success = false;
    outputs.answer = 'No search query provided.';
    outputs.articles = '[]';
    return;
  }

  gs.info('Banking Voice Agent - Search_Knowledge_Base query: ' + query);

  var results = [];

  // Search KB articles using text search
  var gr = new GlideRecord('kb_knowledge');
  gr.addQuery('workflow_state', 'published');
  gr.addQuery('active', true);
  var qc = gr.addQuery('short_description', 'CONTAINS', query);
  qc.addOrCondition('text', 'CONTAINS', query);
  gr.setLimit(5);
  gr.orderByDesc('sys_updated_on');
  gr.query();

  while (gr.next()) {
    results.push({
      title: gr.getValue('short_description') || '',
      snippet: (gr.getValue('text') || '').substring(0, 500),
      number: gr.getValue('number') || '',
      sys_id: gr.getUniqueValue()
    });
  }

  if (results.length > 0) {
    outputs.success = true;
    outputs.answer = results[0].snippet;
    outputs.articles = JSON.stringify(results);
    outputs.article_count = results.length;
  } else {
    outputs.success = false;
    outputs.answer = 'No knowledge articles found for query: ' + query + '. I will need to connect you with a specialist.';
    outputs.articles = '[]';
    outputs.article_count = 0;
  }
})(inputs, outputs);
